package com.bookrush.readerbffservice.api;
import java.security.Principal; import java.util.Map; import jakarta.servlet.http.HttpServletRequest; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpHeaders; import org.springframework.web.bind.annotation.*; import org.springframework.web.client.RestClient; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus;
@RestController @RequestMapping("/api/v1/reader") public class ReaderBffController { private final RestClient rec; public ReaderBffController(@Value("${RECOMMENDATION_URL:http://recommendation-service:8098}") String url){rec=RestClient.builder().baseUrl(url).build();} @GetMapping("/feed") public Map<?,?> feed(@RequestParam(defaultValue="20") int size, Principal principal, HttpServletRequest request){if(principal==null) throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"authentication required"); String bearer=request.getHeader(HttpHeaders.AUTHORIZATION); return rec.get().uri("/api/v1/recommendations/feed?size="+Math.min(size,100)).headers(h->{if(bearer!=null) h.set(HttpHeaders.AUTHORIZATION,bearer);}).retrieve().body(Map.class);} }
